-- Currency a creature pays straight into the currency tab when it dies (Justice, Valor and others from bosses).
-- Name and columns follow alexkulya's 5.4.8 table; lootmode is a plain difficulty bitmask here:
-- bit (1 << DifficultyID), 0 = any difficulty. Rows key the base creature entry.
-- count is in storage units: hundredths for high precision currencies (2400 = 24 Justice Points).
CREATE TABLE IF NOT EXISTS `creature_loot_currency` (
  `entry` mediumint(8) unsigned NOT NULL,
  `lootmode` int(10) unsigned NOT NULL DEFAULT 0,
  `currency` smallint(5) unsigned NOT NULL,
  `count` int(10) unsigned NOT NULL,
  PRIMARY KEY (`entry`, `currency`, `lootmode`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- Rows from the alexkulya/pandaria_5.4.8 world DB (2026_08_16 release).
